public static void register(CommandDispatcher<ServerCommandSource> dispatcher, CommandRegistryAccess registryAccess, CommandManager.RegistrationEnvironment environment) {
        var root = literal("numismatic").build();

        var balance = literal("balance").executes(NumismaticCommand::getSelf).build();
        var detailedBalance = argument("player", EntityArgumentType.players())
            .requires(src -> src.hasPermissionLevel(2))
            .then(literal("get").executes(NumismaticCommand::get))
            .then(longSubcommand("set", "value", NumismaticCommand::set))
            .then(longSubcommand("add", "amount", NumismaticCommand.modify(1)))
            .then(longSubcommand("subtract", "amount", NumismaticCommand.modify(-1)))
            .build();
        var serverWorth = literal("serverworth").executes(NumismaticCommand::serverWorth).build();
        balance.addChild(detailedBalance);

        root.addChild(balance);
        root.addChild(serverWorth);

        dispatcher.getRoot().addChild(root);
    }

private static int getSelf(CommandContext<ServerCommandSource> src) {
        var player = src.getSource().getPlayer();
        if (player == null) return 0;

        var coins = ModComponents.CURRENCY.get(player).getValue();

        printBalance(src.getSource(), coins);

        return (int) coins;
    }

private static LiteralArgumentBuilder<ServerCommandSource> longSubcommand(String name, String argName, Command<ServerCommandSource> command) {
        return literal(name).then(argument(argName, LongArgumentType.longArg(0)).executes(command));
    }

private static void printBalance(ServerCommandSource src, long balance) {
        var values = CurrencyResolver.splitValues(balance);
        src.sendFeedback(() -> Text.translatable("chat.numismatic-overhaul.balance", values[0], values[1], values[2]), false);
    }

private static void printBalancePlayer(ServerCommandSource src, long balance, String playerName) {
        var values = CurrencyResolver.splitValues(balance);
        src.sendFeedback(() -> Text.translatable("chat.numismatic-overhaul.balance.player", playerName, values[0], values[1], values[2]), false);
    }

@SuppressWarnings("ConstantConditions")
    private static int serverWorth(CommandContext<ServerCommandSource> context) {
        final var playerManager = context.getSource().getServer().getPlayerManager();

        var onlineUUIDs = playerManager.getPlayerList().stream().map(Entity::getUuid).toList();
        var offlineUUIDs = OfflineDataLookup.savedPlayers().stream().filter(uuid -> !onlineUUIDs.contains(uuid)).toList();

        long serverWorth = 0;
        for (var onlineId : onlineUUIDs) {
            serverWorth += ModComponents.CURRENCY.get(playerManager.getPlayer(onlineId)).getValue();
        }

        for (var offlineId : offlineUUIDs) {
            serverWorth += OfflineDataLookup.get(offlineId).getCompound("cardinal_components").getCompound("numismatic-overhaul:currency").getLong("Value");
        }

        long finalServerWorth = serverWorth;
        context.getSource().sendFeedback(() -> TextOps.withColor("numismatic §> server net worth: " + finalServerWorth,
                Currency.GOLD.getNameColor(), TextOps.color(Formatting.GRAY)), false);

        return (int) serverWorth;
    }

private static int set(CommandContext<ServerCommandSource> context) throws CommandSyntaxException {
        final var value = LongArgumentType.getLong(context, "value");
        final var players = EntityArgumentType.getPlayers(context, "player");

        for (var player : players) {
            //noinspection deprecation
            ModComponents.CURRENCY.get(player).setValue(value);
            context.getSource().sendFeedback(() -> TextOps.withColor("numismatic §> balance of " + player.getEntityName() + " set to: " + value,
                    Currency.GOLD.getNameColor(), TextOps.color(Formatting.GRAY)), false);
        }

        return CurrencyConverter.asInt(value);
    }

private static int get(CommandContext<ServerCommandSource> context) throws CommandSyntaxException {
        final var players = EntityArgumentType.getPlayers(context, "player");
        long totalBalance = 0;

        for (var player : players) {
            final long balance = ModComponents.CURRENCY.get(player).getValue();
            totalBalance += balance;

            printBalancePlayer(context.getSource(), balance, player.getEntityName());
        }

        return CurrencyConverter.asInt(totalBalance);
    }

private static Command<ServerCommandSource> modify(long multiplier) {
        return context -> {
            final var amount = LongArgumentType.getLong(context, "amount");
            final var players = EntityArgumentType.getPlayers(context, "player");

            long lastValue = 0;

            for (var player : players) {
                final var currencyComponent = ModComponents.CURRENCY.get(player);

                currencyComponent.silentModify(amount * multiplier);
                lastValue = currencyComponent.getValue();

                context.getSource().sendFeedback(() -> TextOps.withColor("numismatic §> balance of " + player.getEntityName() + " set to: " + currencyComponent.getValue(),
                        Currency.GOLD.getNameColor(), TextOps.color(Formatting.GRAY)), false);
            }

            return CurrencyConverter.asInt(lastValue);
        };
    }

@Override
    public void onInitialize() {
        // this type of code truly feels like DH code
        ServerLifecycleEvents.SERVER_STARTED.register(NumismaticOverhaul::loadMobDropConfig);

        FieldRegistrationHandler.register(NumismaticOverhaulItems.class, MOD_ID, false);
        FieldRegistrationHandler.register(NumismaticOverhaulBlocks.class, MOD_ID, false);
        FieldRegistrationHandler.register(NumismaticOverhaulBlocks.Entities.class, MOD_ID, false);

        Registry.register(Registries.SOUND_EVENT, PIGGY_BANK_BREAK.getId(), PIGGY_BANK_BREAK);
        Registry.register(Registries.LOOT_POOL_ENTRY_TYPE, id("money_bag"), MONEY_BAG_ENTRY);

        Registry.register(Registries.SCREEN_HANDLER, id("shop"), SHOP_SCREEN_HANDLER_TYPE);
        Registry.register(Registries.SCREEN_HANDLER, id("piggy_bank"), PIGGY_BANK_SCREEN_HANDLER_TYPE);

        CHANNEL.registerServerbound(RequestPurseActionC2SPacket.class, RequestPurseActionC2SPacket::handle);
        CHANNEL.registerServerbound(ShopScreenHandlerRequestC2SPacket.class, ShopScreenHandlerRequestC2SPacket::handle);
        CHANNEL.registerServerbound(PawnShopScreenHandlerRequestC2SPacket.class, PawnShopScreenHandlerRequestC2SPacket::handle);
        UpdateShopScreenS2CPacket.initialize();
        UpdatePawnShopScreenS2CPacket.initialize();

        ResourceManagerHelper.get(ResourceType.SERVER_DATA).registerReloadListener(new VillagerTradesResourceListener());
        VillagerTradesHandler.registerDefaultAdapters();

        CommandRegistrationCallback.EVENT.register(NumismaticCommand::register);

        ServerLifecycleEvents.END_DATA_PACK_RELOAD.register((server, serverResourceManager, success) -> {
            VillagerTradesHandler.broadcastErrors(server);
            NumismaticOverhaul.reloadMobDropConfig();
        });

        NUMISMATIC_GROUP.initialize();

        if (CONFIG.generateCurrencyInChests()) {
            LootOps.injectItem(NumismaticOverhaulItems.GOLD_COIN, .01f, LootTables.STRONGHOLD_LIBRARY_CHEST, LootTables.BASTION_TREASURE_CHEST, LootTables.STRONGHOLD_CORRIDOR_CHEST,
                LootTables.PILLAGER_OUTPOST_CHEST, LootTables.BURIED_TREASURE_CHEST, LootTables.SIMPLE_DUNGEON_CHEST, LootTables.ABANDONED_MINESHAFT_CHEST);

            LootTableEvents.MODIFY.register((resourceManager, lootManager, id, tableBuilder, source) -> {
                if (anyMatch(id, LootTables.DESERT_PYRAMID_CHEST)) {
                    tableBuilder.pool(LootPool.builder().with(MoneyBagLootEntry.builder(CONFIG.lootOptions.desertMinLoot(), CONFIG.lootOptions.desertMaxLoot()))
                        .conditionally(RandomChanceLootCondition.builder(0.45f)));
                } else if (anyMatch(id, LootTables.SIMPLE_DUNGEON_CHEST, LootTables.ABANDONED_MINESHAFT_CHEST)) {
                    tableBuilder.pool(LootPool.builder().with(MoneyBagLootEntry.builder(CONFIG.lootOptions.dungeonMinLoot(), CONFIG.lootOptions.dungeonMaxLoot()))
                        .conditionally(RandomChanceLootCondition.builder(0.75f)));
                } else if (anyMatch(id, LootTables.BASTION_TREASURE_CHEST, LootTables.STRONGHOLD_CORRIDOR_CHEST, LootTables.PILLAGER_OUTPOST_CHEST, LootTables.BURIED_TREASURE_CHEST)) {
                    tableBuilder.pool(LootPool.builder().with(MoneyBagLootEntry.builder(CONFIG.lootOptions.structureMinLoot(), CONFIG.lootOptions.structureMaxLoot()))
                        .conditionally(RandomChanceLootCondition.builder(0.75f)));
                } else if (anyMatch(id, LootTables.STRONGHOLD_LIBRARY_CHEST)) {
                    tableBuilder.pool(LootPool.builder().with(MoneyBagLootEntry.builder(CONFIG.lootOptions.strongholdLibraryMinLoot(), CONFIG.lootOptions.strongholdLibraryMaxLoot()))
                        .conditionally(RandomChanceLootCondition.builder(0.85f)));
                }
            });
        }
    }

private static boolean anyMatch(Identifier target, Identifier... comparisons) {
        for (Identifier comparison : comparisons) {
            if (target.equals(comparison)) return true;
        }
        return false;
    }

