public CurrencyTooltipComponent(CurrencyTooltipData data) {
        this.data = data;
        this.text = new ArrayList<>();

        if (data.original()[0] != -1) {
            CurrencyConverter.getAsItemStackList(data.original()).forEach(stack -> text.add(createPlaceholder(stack.getCount())));
            text.add(Text.of(" "));
        }

        CurrencyConverter.getAsItemStackList(data.value()).forEach(stack -> text.add(createPlaceholder(stack.getCount())));
    }

@Override
    public int getHeight() {
        return 10 * text.size();
    }

@Override
    public int getWidth(TextRenderer textRenderer) {
        if (widthCache == -1) {
            widthCache = textRenderer.getWidth(text.stream()
                    .max(Comparator.comparingInt(textRenderer::getWidth)).orElse(Text.of("")));
        }
        return widthCache;
    }

@Override
    public void drawText(TextRenderer textRenderer, int x, int y, Matrix4f matrix4f, VertexConsumerProvider.Immediate immediate) {
        for (int i = 0; i < text.size(); i++) {
            textRenderer.draw(text.get(i), x, y + i * 10, -1, true, matrix4f, immediate, TextRenderer.TextLayerType.NORMAL, 0, LightmapTextureManager.MAX_LIGHT_COORDINATE);
        }
    }

@Override
    public void drawItems(TextRenderer textRenderer, int x, int y, DrawContext context) {
        List<ItemStack> originalCoins = data.original()[0] != -1 ? CurrencyConverter.getAsItemStackList(data.original()) : new ArrayList<>();
        List<ItemStack> coins = CurrencyConverter.getAsItemStackList(data.value());

        for (int i = 0; i < originalCoins.size(); i++) {
            context.drawTexture(new Identifier("textures/gui/container/villager2.png"), x + (originalCoins.get(i).getCount() > 9 ? 14 : 11), y + 3, 0, 176, 9, 2, 512, 256);
            context.drawItemWithoutEntity(ItemOps.singleCopy(originalCoins.get(i)), x - 4, y - 5 + i * 10);
        }

        for (int i = 0; i < coins.size(); i++) {
            context.drawItemWithoutEntity(ItemOps.singleCopy(coins.get(i)), x - 4, y - 5 + i * 10 + (originalCoins.size() == 0 ? 0 : 10 + originalCoins.size() * 10));
        }
    }

private static Text createPlaceholder(int count) {
        String placeholder = "§7   " + count + " ";
        return Text.literal(placeholder).formatted(Formatting.GRAY);
    }

public static void renderTooltip(long value, DrawContext context, Text title, int x, int y) {

        List<Text> tooltip = new ArrayList<>();
        tooltip.add(title);

        y += 10;

        List<ItemStack> coins = CurrencyConverter.getAsItemStackList(value);

        // Push the item stack renderers forward, so they do not get obscured by the tooltip background
        context.getMatrices().translate(0, 0, 500);

        for (int i = 0; i < coins.size(); i++) {
            renderStack(context, coins.get(i), tooltip, i, x, y);
        }

        context.getMatrices().translate(0, 0, -500);

        if (tooltip.size() == 1) {
            tooltip.add(Text.translatable("numismatic-overhaul.empty").formatted(Formatting.GRAY));
        }


        context.drawTooltip(MinecraftClient.getInstance().textRenderer, tooltip, x, y - 15);
    }

private static void renderStack(DrawContext context, ItemStack stack, List<Text> tooltip, int index, int x, int y) {
        tooltip.add(createPlaceholder(String.valueOf(stack.getCount())));

        ItemStack toRender = stack.copy();
        toRender.setCount(1);

        int localX = x + 8;
        int localY = y - (2 - index) * 10;

        context.drawItemWithoutEntity(toRender, localX, localY);
    }

private static Text createPlaceholder(String text) {
        String placeholder = "§7   " + text + " ";
        return Text.of(placeholder);
    }

